begin;
create temp table member_access_test_results(check_name text,passed boolean);
do $$
declare administrator uuid; target uuid; target_email text; admin_email text; current_version bigint; initial_count bigint; initial_audit bigint; initial_suspend bigint; result jsonb; overview jsonb; denied boolean;
begin
 select a.user_id,u.email into administrator,admin_email from private_website_lab.admins a join auth.users u on u.id=a.user_id where u.email_confirmed_at is not null limit 1;
 select u.id,u.email into target,target_email from auth.users u where u.email_confirmed_at is not null and private_website_lab.account_allowed(u.id) and not exists(select 1 from private_website_lab.admins where user_id=u.id) and not exists(select 1 from private_opportunity_pipeline.admins where user_id=u.id) limit 1;
 if administrator is null or target is null then raise exception 'Staging admin/member fixtures required';end if;
 perform set_config('request.jwt.claim.sub',target::text,true);
 denied:=false;begin perform public.website_manage_members('list');exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Ordinary member reached admin directory';end if;
 insert into member_access_test_results values('ordinary member denied admin access',true);
 perform set_config('request.jwt.claim.sub',administrator::text,true);
 result:=public.website_manage_members('list');if jsonb_array_length(result->'members')=0 then raise exception 'Admin directory empty';end if;
 overview:=result->'overview'; if (overview->>'members')::bigint<>(select count(*) from auth.users where deleted_at is null) then raise exception 'Directory overview excludes registered accounts';end if;
 result:=public.website_manage_members('list',jsonb_build_object('q',admin_email));if (result->>'total')::int<>1 or result->'overview'<>overview then raise exception 'Search changed global overview';end if;
 insert into member_access_test_results values('all registered accounts counted and overview independent of search',true);
 select count(*),count(*) filter(where action='suspend') into initial_audit,initial_suspend from private_website_lab.member_access_audit where user_id=target;
 result:=public.website_manage_members('detail',jsonb_build_object('user_id',target));current_version:=(result->>'version')::bigint;
 denied:=false;begin perform public.website_manage_members('suspend',jsonb_build_object('user_id',administrator,'version',0,'reason','Fixture administrator protection','confirmation',admin_email));exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Self/admin suspension allowed';end if;
 insert into member_access_test_results values('administrator directory and protected administrator accounts',true);
 perform public.website_manage_members('suspend',jsonb_build_object('user_id',target,'version',current_version,'reason','Fixture suspension — rollback only','confirmation',target_email));
 if private_website_lab.account_allowed(target) then raise exception 'Suspension did not take effect';end if;
 if (select count(*) from private_website_lab.member_access_audit where user_id=target and action='suspend')<>initial_suspend+1 then raise exception 'Suspension audit missing';end if;
 denied:=false;begin perform public.website_manage_members('restore',jsonb_build_object('user_id',target,'version',current_version,'reason','Fixture stale restore test','confirmation',target_email));exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'Stale version allowed';end if;
 perform set_config('request.jwt.claim.sub',target::text,true);perform set_config('request.path','/rpc/website_lab',true);
 denied:=false;begin perform public.website_request_guard();exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Existing identity bypassed request guard';end if;
 perform set_config('request.path','/rpc/website_account_access',true);perform public.website_request_guard();result:=public.website_account_access();
 if (result->>'allowed')::boolean then raise exception 'Suspended self-check reports access';end if;
 execute 'set local role authenticated';
 select count(*) into initial_count from public.profiles where id=target;
 if initial_count<>0 then raise exception 'Suspended profile read allowed';end if;
 execute 'reset role';
 insert into member_access_test_results values('existing identity blocked by database guard and profile RLS',true);
 if exists(select 1 from jsonb_array_elements(public.website_lab_weekly_pulse('preview')) x where x->>'user_id'=target::text) then raise exception 'Suspended member in weekly pulse';end if;
 insert into member_access_test_results values('suspended recipients excluded from weekly pulse',true);
 perform set_config('request.jwt.claim.sub',administrator::text,true);
 perform public.website_manage_members('restore',jsonb_build_object('user_id',target,'version',current_version+1,'reason','Fixture restoration — rollback only','confirmation',target_email));
 if not private_website_lab.account_allowed(target) then raise exception 'Restoration failed';end if;
 if (select count(*) from private_website_lab.member_access_audit where user_id=target)<>initial_audit+2 then raise exception 'Access history missing';end if;
 perform set_config('request.jwt.claim.sub',target::text,true);perform set_config('request.path','/rpc/website_lab',true);perform public.website_request_guard();
 insert into member_access_test_results values('restoration re-enables existing identity and records both actions',true);
end $$;
select * from member_access_test_results;
rollback;
